cat > <repo>/internal/doctor/zz_sfh_probe_test.go <<'EOF'
package doctor

import (
	"os"
	"path/filepath"
	"testing"
)

func mkEnabled(t *testing.T, file, body string) string {
	t.Helper()
	dir := t.TempDir()
	hooksDir := filepath.Join(dir, ".git", "hooks")
	if err := os.MkdirAll(hooksDir, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(hooksDir, file), []byte(body), 0o755); err != nil {
		t.Fatal(err)
	}
	zone := filepath.Join(dir, ".punt-labs", "ethos")
	if err := os.MkdirAll(zone, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(zone, "enabled"), nil, 0o644); err != nil {
		t.Fatal(err)
	}
	return dir
}

// Shebang-less host hook + chained ethos section. git runs this fine (proven
// empirically); doctor exec's it directly and gets ENOEXEC.
func TestProbe_ShebangLessHost(t *testing.T) {
	body := "true\n# --- BEGIN ETHOS DES-058 SEAL ---\nethos audit seal || exit 2\n# --- END ETHOS DES-058 SEAL ---\n"
	r := CheckSealHook(mkEnabled(t, "pre-commit", body))
	t.Logf("status=%s detail=%s", r.Status, r.Detail)
}

// Host section that fails for an environmental reason inside the sandbox
// (an empty repo with no staged files), then the chained ethos section.
func TestProbe_HostFailsInSandbox(t *testing.T) {
	body := "#!/bin/sh\ngit diff --cached --name-only | grep -q . || exit 1\n" +
		"# --- BEGIN ETHOS DES-058 SEAL ---\nethos audit seal || exit 2\n# --- END ETHOS DES-058 SEAL ---\n"
	r := CheckSealHook(mkEnabled(t, "pre-commit", body))
	t.Logf("status=%s detail=%s", r.Status, r.Detail)
}

// Dormant repo (no marker) with a foreign shell hook: is the foreign hook
// executed anyway?
func TestProbe_DormantExecutesForeignHook(t *testing.T) {
	dir := t.TempDir()
	hooksDir := filepath.Join(dir, ".git", "hooks")
	if err := os.MkdirAll(hooksDir, 0o755); err != nil {
		t.Fatal(err)
	}
	witness := filepath.Join(t.TempDir(), "ran")
	body := "#!/bin/sh\n: > " + witness + "\n"
	if err := os.WriteFile(filepath.Join(hooksDir, "pre-commit"), []byte(body), 0o755); err != nil {
		t.Fatal(err)
	}
	r := CheckSealHook(dir)
	_, err := os.Stat(witness)
	t.Logf("status=%s detail=%s foreignHookExecuted=%v", r.Status, r.Detail, err == nil)
}
EOF
cd <repo> && go test ./internal/doctor/ -run 'TestProbe' -v 2>&1 | head -40

