	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "implement.yaml"),
		[]byte("name: implement\nthis is: [not, valid\n  yaml: ::\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	r := CheckDelegatedWorkerArchetypes(root)
	t.Logf("corrupt-yaml   -> status=%s detail=%s", r.Status, r.Detail)

	// And an unreadable file.
	p := filepath.Join(dir, "test.yaml")
	if err := os.WriteFile(p, []byte("name: test\nrequire_delegated_worker: true\n"), 0o000); err != nil {
		t.Fatal(err)
	}
	r2 := CheckDelegatedWorkerArchetypes(root)
	t.Logf("unreadable     -> status=%s detail=%s", r2.Status, r2.Detail)
}
