cat > <repo>/internal/doctor/zz_sfh_probe2_test.go <<'EOF'
package doctor

import (
	"os"
	"path/filepath"
	"testing"
)

func writeArch(t *testing.T, root, name, body string, mode os.FileMode) {
	t.Helper()
	dir := filepath.Join(root, ".punt-labs", "ethos", "archetypes")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, name), []byte(body), mode); err != nil {
		t.Fatal(err)
	}
}

func TestProbe_CorruptArchetype(t *testing.T) {
	t.Setenv("HOME", t.TempDir()) // isolate from the real global store

	t.Run("malformed yaml", func(t *testing.T) {
		root := t.TempDir()
		writeArch(t, root, "implement.yaml", "name: implement\n  bad: [unclosed\n\tmixed: ::\n", 0o644)
		writeArch(t, root, "test.yaml", "name: test\nrequire_delegated_worker: true\n", 0o644)
		r := CheckDelegatedWorkerArchetypes(root)
		t.Logf("malformed implement.yaml -> status=%s detail=%s", r.Status, r.Detail)
	})

	t.Run("unreadable file", func(t *testing.T) {
		root := t.TempDir()
		writeArch(t, root, "implement.yaml", "name: implement\nrequire_delegated_worker: true\n", 0o000)
		writeArch(t, root, "test.yaml", "name: test\nrequire_delegated_worker: true\n", 0o644)
		r := CheckDelegatedWorkerArchetypes(root)
		t.Logf("unreadable implement.yaml -> status=%s detail=%s", r.Status, r.Detail)
	})

	t.Run("healthy control", func(t *testing.T) {
		root := t.TempDir()
		writeArch(t, root, "implement.yaml", "name: implement\nrequire_delegated_worker: true\n", 0o644)
		writeArch(t, root, "test.yaml", "name: test\nrequire_delegated_worker: true\n", 0o644)
		r := CheckDelegatedWorkerArchetypes(root)
		t.Logf("healthy                   -> status=%s detail=%s", r.Status, r.Detail)
	})
}
EOF
